// EEP-Live-Erweiterung (nutzt auch das Info-Popup), generated by Claude AI
"use strict";
/* global
	global:readonly,
	Signalstellung:readonly,
	_:readonly,
	msg:readonly,
	TrackSystemText:readonly,
	showInfoWindow:readonly
*/
/* Interface
required glogal functions:
	_
	msg
	TrackSystemText
	showInfoWindow
required global data:
	Signalstellung
	global (u.a. global.Gleissysteme, global.TrackSystem, global.trackConnections, global.Meldungen, global.SvgPanZoom)
*/
(function(){
const ch = new BroadcastChannel("EEP_LIVE"), NS = "http://www.w3.org/2000/svg";

const SIGNAL_COLORS = {halt:"rgb(220,0,0)" /* red */, fahrt:"rgb(0,170,0)" /* green */, warn:"rgb(230,140,0)" /* orange */, none:"rgb(128,128,128)" /* grey */};
const SWITCH_COLORS = {1:"rgb(0,110,200)" /* blue */, 2:"rgb(220,120,0)" /* orange */, 3:"rgb(160,0,200)" /* purple */};
const TRAIN_COLOR   = "rgb(255,140,0)" /* orange */;
const GEARS_COLOR   = "rgb(100,40,0)" /* brown */;

// Meldung nur einmal ausgeben (Debugging ohne Log-Flut bei jedem Datensatz)
const warned = {};
function warnOnce(key, ...args){
	if (!warned[key]) { warned[key] = true; console.warn("EEP-Live:", ...args); }
}

// SVG-Element erzeugen
function el(parent, tag, attributes){
	const element = document.createElementNS(NS, tag);
	for (const key in attributes) { element.setAttribute(key, attributes[key]); }
	parent.appendChild(element);
	return element;
}

// Ist eine Anlage-Datei geladen und der Gleisplan aufgebaut?
// (global.SvgPanZoom wird erst am Ende von loadFile gesetzt)
function isLoaded(){
	return !!(window.global && global.SvgPanZoom && global.Gleissysteme && Object.keys(global.Gleissysteme).length);
}

// ---- Signalstellungen ----------------------------------------------------
// Abbildung des Stellungstextes auf -> halt | fahrt | warn | null (unbekannt = grau)
function classify(text){
	text = String(text || "").trim().toLowerCase();
	if (!text) return null;

	if (/^(halt|stop|danger)\b.*(erwarten|expect)/.test(text)) return "warn";
	if (/^(halt|stop|danger|hp ?0|rot|close|geschlossen|schranke geschlossen)|gesperrt/.test(text)) return "halt";
	if (/^(fahrt|go|clear|open|offen|frei|gehen|schranke offen|sh1|ziel)/.test(text)) return "fahrt";
	if (/erwarten|expect/.test(text)) return "warn";
	return null;
}
// Liefere den Text in Deutsch bzw. in Ersatzsprache Englisch
function txt(o){ return typeof o === "string" ? o : (o ? (o.DE || o.EN || "") : ""); }

// Lese die Signalstellungen und speichere sie in Kleinbuchstaben
let lc = null;
function sigDef(file){
	if (typeof Signalstellung === "undefined") return null;   // Globale Variable von js/EEP_Signale_Daten.js

	if (Signalstellung[file]) return Signalstellung[file];

	// Speichere die Signalstellungen in Kleinbuchstaben
	if (!lc) {
		lc = {};
		for (const k in Signalstellung) { lc[k.toLowerCase()] = Signalstellung[k]; }
	}
	return lc[String(file).toLowerCase()] || null;
}

// Liefere die klassifizierten Signalstellungen der Signale
function signalInfo(ids){
	if (!window.global || !global.Meldungen || !Object.keys(global.Meldungen).length) return null; // .anl3 noch nicht geladen

	const out = {};
	for (const id of ids) {
		const Meldung = global.Meldungen[id];
		if (!Meldung) continue;

		const d = sigDef(Meldung.getAttribute("name"));
		if (!d) continue;

		const pos = {};
		for (const n in d.Pos) {
			const t = txt(d.Pos[n]);
			pos[n] = {text: t, cls: classify(t)};
		}
		out[id] = {name: txt(d.Name), pos: pos};
	}
	return out;
}

// ---- Gleise finden -----------------------------------------------------------
// Die Gleissystem-Nummer des Exports entspricht der GleissystemID der Anlage-Datei.
function getGleis(GleissystemID, GleisID){
	const Gleis = window.global && global.Gleissysteme && global.Gleissysteme[GleissystemID] && global.Gleissysteme[GleissystemID][GleisID];
	if (!Gleis) {
		warnOnce("find" + GleissystemID + "-" + GleisID, `Gleis ${GleissystemID}-${GleisID} nicht gefunden. Gleissysteme in der Anlage: ${Object.keys((window.global && global.Gleissysteme) || {})}`);
		return null;
	}
	return Gleis;
}

// ---- Gleisgeometrie (EEP-Koordinaten, y nach oben) ---------------------------
// Aus Anfang (mPos), Mitte (mMid) und Ende (mEnd) eines Gleises samt Richtung wird
// eine kubische Hermite-Kurve in zwei Hälften gebildet; f = 0..1 läuft von mPos nach mEnd.
function geom(GleissystemID, GleisID){
	const Gleis = getGleis(GleissystemID, GleisID);
	if (!Gleis) return null;

	if (Gleis._live) return Gleis._live;

	if (!Gleis.mPos || !Gleis.mMid || !Gleis.mEnd || !(Gleis.Laenge > 0)) {
		warnOnce("geom" + GleissystemID + "-" + GleisID,
			`Gleis ${GleissystemID}-${GleisID} ohne Geometrie: mPos ${!!Gleis.mPos}, mMid ${!!Gleis.mMid}, mEnd ${!!Gleis.mEnd}, Laenge ${Gleis.Laenge}, Kurventyp ${Gleis.CurveType}`);
		return null;
	}

	const P = [Gleis.mPos, Gleis.mMid, Gleis.mEnd].map(m => ({x: m[12], y: m[13], tx: m[0], ty: m[1]}));
	const ref = [[P[1].x-P[0].x, P[1].y-P[0].y],  [P[2].x-P[0].x, P[2].y-P[0].y],  [P[2].x-P[1].x, P[2].y-P[1].y]];
	P.forEach((p, i) => {
		const n = Math.hypot(p.tx, p.ty) || 1;
		p.tx /= n;
		p.ty /= n;
		if (p.tx*ref[i][0] + p.ty*ref[i][1] < 0) { p.tx = -p.tx; p.ty = -p.ty; }   // Tangenten gleich ausrichten
	});
	const ok = Math.hypot(P[2].x-P[0].x, P[2].y-P[0].y) > 0.01 && P.every(p => isFinite(p.x) && isFinite(p.y) && isFinite(p.tx) && isFinite(p.ty));
	if (!ok) { 
		warnOnce("geomok" + GleissystemID + "-" + GleisID, `Gleis ${GleissystemID}-${GleisID}: Geometrie unbrauchbar (Anfang = Ende oder NaN)`); 
		return null; 
	}
	return Gleis._live = {Gleis: Gleis, GleissystemID: GleissystemID, id: GleisID, P: P, Laenge: Gleis.Laenge};
}
// kubische Hermite-Spline-Interpolation
// a: Startpunkt
// b: Endpunkts
// h: Ein Skalierungsfaktor für die Tangenten (Länge)
// u: Der Interpolationsfaktor. Er läuft von 0 (Startpunkt a) bis 1 (Endpunkt b).
function herm(a, b, h, u){
	const u2 = u*u, u3 = u2*u;
	const h00 = 2*u3-3*u2+1, h10 = u3-2*u2+u, h01 = -2*u3+3*u2, h11 = u3-u2; // Hermite-Basisfunktionen (Polynome 3. Grades)
	const x = h00*a.x + h10*h*a.tx + h01*b.x + h11*h*b.tx;
	const y = h00*a.y + h10*h*a.ty + h01*b.y + h11*h*b.ty;  
	return {x: x, y: y};
}
function at(G, f){
	f = Math.max(0, Math.min(1, f));
	return f < 0.5 ? herm(G.P[0], G.P[1], G.Laenge/2, f*2) : herm(G.P[1], G.P[2], G.Laenge/2, f*2-1);
}
const dist = (a, b) => Math.hypot(a.x-b.x, a.y-b.y);

let cur = null;   // zuletzt empfangene Daten (für die Weichenstellungen)
function switchState(g){
	const s = cur && cur.switches && cur.switches[g.getAttribute("Key_Id")];
	return s ? s.state : 1;
}

// ---- Lage der Fahrzeuge auf dem Gleis -----------------------------------------
// track.position wird immer vom Gleisanfang (mPos) gerechnet, unabhängig von track.direction.
// Liefert den Anteil f (0..1) vom Gleisanfang mPos zum Gleisende mEnd.
function fractionOf(v, G){
	return Math.min(Math.max(v.track.position / G.Laenge, 0), 1);
}

// Läuft ab dem Punkt f (0..1 vom Gleisanfang mPos zum Gleisende mEnd) in Richtung sgn (+1: f wächst, -1: f nimmt ab)
// len Meter über das Gleisnetz. vx/vy: bekannter Startpunkt in Weltkoordinaten.
// Liefert Punkte [{x, y, s}] mit s = zurückgelegte Strecke in m, oder null.
// Wo sich das Gleisnetz verzweigt, wird das Gleis bevorzugt, auf dem Fahrzeuge des Zuges stehen (onTrain), sonst gilt die Weichenstellung.
// Ist die Gleisverbindung virtuell (Flags = 1)?
const isVirtual = connection => !!(connection && connection.Flags != null && Number(connection.Flags) === 1);

// Endpunkt: läuft ab Punkt f (0..1 von mPos nach mEnd) in Richtung sgn (+1/-1) len Meter über das Gleisnetz.
// Virtuelle Verbindungen werden nicht überschritten (Ende = Verbindungsstelle).
function endPoint(system, gleisID, f, sgn, len, hint) {
	let G = geom(system, gleisID);
	if (!G) return null;
	let rest = len;
	let q = null;
	for (let hop = 0; hop < 30; hop++) {
		const toEnd = (sgn > 0 ? 1 - f : f) * G.Laenge;
		if (rest <= toEnd) return at(G, f + sgn * rest / G.Laenge);   // Ende liegt auf diesem Gleis

		rest -= toEnd;
		q = at(G, sgn > 0 ? 1 : 0);                                  // Gleisende erreicht

		// Nachbargleis
		const conns = (global.trackConnections && global.trackConnections[system] && global.trackConnections[system][gleisID]) || {};
		let next;
		if (sgn < 0) {
			next = conns.Anfang;
		} else {
			const cand = [conns.Ende, conns.EndeAbzweig, conns.EndeKoAbzweig].filter(Boolean);
			next = cand.find(c => hint && c.GleisID === hint)        // Gleis des Folgefahrzeuges bevorzugen
				|| (() => {
					const st = switchState(G.Gleis);
					return (st === 2 && conns.EndeAbzweig) || (st === 3 && conns.EndeKoAbzweig) || conns.Ende || conns.EndeAbzweig;
				})();
		}
		if (!next || isVirtual(next)) return q;

		gleisID = next.GleisID;
		G = geom(system, gleisID);
		if (!G) return q;
		// Eintritt am näheren Ende des Nachbargleises
		if (dist(G.P[0], q) <= dist(G.P[2], q)) { f = 0; sgn = 1; } else { f = 1; sgn = -1; }
	}
	return q;
}

// Ende eines Fahrzeuges (Anfang = vehicle.position)
function vehicleEnd(vehicle, nextV) {
	const track = vehicle.track;
	if (!track || !vehicle.position) return null;
	const G = geom(track.system, track.id);
	if (!G) return null;
	// Richtung vom Anfang zum Ende aus Gleisrichtung und Ausrichtung des Fahrzeuges
	const sgn = (track.direction === 1 ? 1 : -1) * (vehicle.forward === false ? -1 : 1) > 0 ? -1 : 1;
	const hint = (nextV && nextV.track && nextV.track.system === track.system) ? nextV.track.id : null;
	return endPoint(track.system, track.id, fractionOf(vehicle, G), sgn, vehicle.length || 0, hint);
}

// ---- Zeichnen -------------------------------------------------------------------
let liveLayer;

function draw(d){
	// Ohne geladene Anlage-Datei gibt es nichts, worauf gezeichnet werden könnte
	if (!isLoaded()) return;
	cur = d;
	const root = document.getElementById("sutrackpSVG");

	// Ändere die Farbe von Signalen
	const info = signalInfo(Object.keys(d.signals || {})) || {};
	for (const id in d.signals || {}) {
		const state = d.signals[id].state;
		const position = info[id] && info[id].pos[state];
		const color = SIGNAL_COLORS[(position && position.cls) || "none"];
		for (const pre of ["S", "P", "H"]) { // Signal, Vorsignal, Haltelinie
			const signalElement = document.getElementById(pre + id);
			if (!signalElement) continue;

			signalElement.style.stroke = color;
			signalElement.querySelectorAll("text").forEach(text => text.style.fill = color);
		}
	}

	// Ändere die Farbe von Weichen
	for (const id in d.switches || {}) {
		const switchElement = document.getElementById("W" + id);
		const color = SWITCH_COLORS[d.switches[id].state];
		if (switchElement && color) switchElement.style.fill = color;
	}

	// Erneuere die Ebene für die Zugverbände
	if (liveLayer) liveLayer.remove();
	liveLayer = el(root, "g", {
		id: "liveLayer",
		"pointer-events": "none"
	});

	// Gruppe mit height-Klasse (wird von changeHeightRange() ausgewertet) erzeugen
	// und den aktuellen Höhenfilter sofort anwenden, da der liveLayer bei jedem Datensatz neu aufgebaut wird
	function heightGroup(parent, z){
		const h = +(+z || 0).toFixed(2);
		const g = el(parent, "g", {"class": `height=${h.toFixed(2)}`});
		const r = global.heightRange;
		if (r && (h < r.minZ || h > r.maxZ)) g.classList.add("hiddenZ");
		return g;
	}

	// Zeichne Zugverbände: jedes Fahrzeug einzeln
	const DASH = "stroke-dasharray:calc(var(--normal-stroke-width)*2) calc(var(--normal-stroke-width)*1.5)";
	for (const trainName in d.trains || {}) {
		//console.log(trainName);
		const train = d.trains[trainName];

		const vehicles = [];     // vehicles[0] = erstes Fahrzeug = Zugspitze
		for (const name of train.vehicles || []) {
			const rs = d.rollingstock[name];
			if (rs && rs.exists !== false) vehicles.push(Object.assign({name: name}, rs));
		}
		if (!vehicles.length) continue;

		// Class live verhindert die Färbung gemäß Gleissystem, class TrackSystemCode erlaubt das verstecken des Elements
		const systemCode = global.TrackSystemCode[global.TrackSystem[train.track.system]];
		const liveTrain = el(liveLayer, "g", {id: "liveTrain" + trainName, "class" : `live ${systemCode}`});

		// Aktuellen Status der Checkbox des Gleissystems übernehmen, da der liveLayer bei jedem Datensatz neu aufgebaut wird
		const systemCheckbox = document.querySelector(`input[type="checkbox"][name="${systemCode}"]`);
		if (systemCheckbox && !systemCheckbox.checked) {
			liveTrain.classList.add("hidden");
		}

		// Anfang = Fahrzeugposition, Ende = näherungsweise auf dem Gleis
		const ends = vehicles.map((v, i) => vehicleEnd(v, vehicles[i+1]));
		//console.log(trainName);
		//console.log("train", train, train.position.x, train.position.y);
		//console.log("vehicles", vehicles, vehicles[0].position.x, vehicles[0].position.y);
		//console.log("paths", paths);

		// Name des Zugverbandes an der Zugspitze
		const tip = vehicles[0].position;
		el(heightGroup(liveTrain, tip.z), "text", {x: tip.x, y: -tip.y - 3.0, fill: TRAIN_COLOR,
			"pointer-events": "visiblePainted", "data-train": trainName}).textContent = `${trainName}, ${train.length.toFixed(1)}m`;
	
		vehicles.forEach((vehicle, i) => {
			const hasGears = vehicle.gears > 0;
			const color = hasGears ? GEARS_COLOR : TRAIN_COLOR;
			const head = vehicle.position, end = ends[i];
			const data = {"data-train": trainName, "data-vehicle": vehicle.name};
			const vg = heightGroup(liveTrain, head.z);   // Höhe des Fahrzeuganfangs

			if (end) {
				const ln = {x1: head.x, y1: -head.y, x2: end.x, y2: -end.y};
				el(vg, "line", Object.assign({fill: "none", stroke: color,
					style: "stroke-width:calc(var(--normal-stroke-width)*" + (hasGears ? 4 : 3) + ");stroke-linecap:round"}, ln));
				el(vg, "line", Object.assign({fill: "none", stroke: "transparent", "pointer-events": "stroke",
					style: "stroke-width:calc(var(--normal-stroke-width)*8);stroke-linecap:round;cursor:pointer"}, ln, data));

				const next = vehicles[i+1];
				if (next && dist(end, next.position) > 0.3) {
					el(vg, "line", {x1: end.x, y1: -end.y, x2: next.position.x, y2: -next.position.y,
						stroke: TRAIN_COLOR, fill: "none", "pointer-events": "none",
						style: "stroke-width:calc(var(--normal-stroke-width)*1.5);" + DASH});
				}
			} else {
				warnOnce("noend" + vehicle.name, `Fahrzeug ${vehicle.name} (${trainName}): Ende nicht berechenbar (Gleis ${vehicle.track && vehicle.track.system}-${vehicle.track && vehicle.track.id})`);
			}

			el(vg, "circle", Object.assign({
				cx: head.x, cy: -head.y,
				r: (i === 0 ? 1.0 : (hasGears ? 0.8 : 0.6)),
				fill: color, style: "fill-opacity:50%", "pointer-events": "all"
			}, data));

			el(vg, "text", Object.assign({
				x: head.x, y: -head.y + 3.0, fill: TRAIN_COLOR, "pointer-events": "visiblePainted"
			}, data)).textContent =
				`${(vehicle.modelType >= 1 && vehicle.modelType <= 15) ? _('modelType_' + vehicle.modelType) : (vehicle.modelType ?? "–")}`
				+ `, ${vehicle.length.toFixed(1)}m`;
		});
	}
}

// ---- Info-Popup für Züge und Fahrzeuge ---------------------------------------
const escH = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num  = (n, d = 1) => (typeof n === "number" ? n.toFixed(d) : "–");
// Übersetzter Text zu modelType (1-15), sonst der Rohwert
const modelTypeText = t => (t >= 1 && t <= 15) ? _('modelType_' + t) : (t != null ? escH(t) : "–");
const couplingText  = t => (t >= 1 && t <= 3)  ? _('coupling_' + t)  : (t != null ? escH(t) : "–");

function sysText(id){
	try { return TrackSystemText(String(id)) || ("Gleissystem " + id); } catch (e) { return "Gleissystem " + id; }
}
function posLink(p){
	if (!p) return "–";
	return `<a href="javascript:void(0);" onclick="javascript:global.SvgPanZoom.centerPosition([${+p.x},${+p.y},${+p.z || 0}]);">${num(p.x, 0)}m, ${num(p.y, 0)}m</a>`;
}
function trackLink(k){
	if (!k) return "–";
	return `<a href="javascript:void(0);" onclick="javascript:showGleisInfo('${Number(k.system)}','${Number(k.id)}');">${escH(sysText(k.system))} ${escH(k.id)}</a> @ ${num(k.position, 0)}m`;
}

function showTrainInfo(name, withVehicles, highlightVehicle){
	const t = cur && cur.trains && cur.trains[name];
	if (!t) return;
	const active = cur.global && cur.global.activeTrain === name;
	//console.log(t);

	let html = `${_('Geschwindigkeit')}: ${num(t.speed)} km/h (${_('Sollgeschwindigkeit')} ${num(t.targetSpeed)} km/h)`
		+ `<br>${_('Länge')}: ${num(t.length)}m, ${_('Fahrzeuge')}: ${t.vehicleCount != null ? t.vehicleCount : (t.vehicles || []).length}`
		+ (t.route ? `<br>${_('Route')}: ${escH(t.route)}` : "")
		+ (active ? `<br><b>${_('aktiverZugverband')}</b>` : "")
		+ `<br><i>${_('Position')}: ${posLink(t.position)} ${_('auf')} ${_('Gleis')} ${trackLink(t.track)}</i>`
		+ `<i>, ${_('Höhe')} ${num(t.position && t.position.z, 2)}m</i>`
		;

	if (withVehicles) {
		html += `<br><br><b>${_('Fahrzeuge')}</b>`;
		(t.vehicles || []).forEach((vn, i) => {
			const v = cur.rollingstock && cur.rollingstock[vn];
			if (!v || v.exists === false) { html += `<br>${i+1}. ${escH(vn)} (${_('nicht vorhanden')})`; return; }
			//console.log(v);
			
			const line = `${i+1}. ${escH(vn)}${v.gears > 0 ? ` (${_('angetrieben')})` : ""}`;
			html += `<br>`+ (vn === highlightVehicle ? "<b>"+line+"</b>" : line)
				+ `<br>&nbsp;&nbsp;${_('Modelltyp')}: ${modelTypeText(v.modelType)}`
				+ `<br>&nbsp;&nbsp;${_('Länge')}: ${num(v.length, 2)}m, ${_('Ausrichtung')}: ${v.forward ? " →" : " ←"}`
				+ `<br>&nbsp;&nbsp;${_('Kupplung')}: ${_('vorne')} ${couplingText(v.couplingFront)}, ${_('hinten')} ${couplingText(v.couplingRear)}`
				+ `<br>&nbsp;&nbsp;<i>${_('Position')}: ${posLink(v.position)} ${_('auf')} ${_('Gleis')} ${trackLink(v.track)}</i>`
				+ `<i>, ${_('Höhe')} ${num(v.position && v.position.z, 2)}m</i>`
				;
		});
	}

	msg("", `${_('Zugverband')} ${name}`);
	showInfoWindow({
		code:  "Zugverband " + name,
		title: `${_('Zugverband')} ${escH(name)}`,
		content: html
	});
}

// Ein Listener für alle Züge (die Ebene wird bei jedem Datensatz neu aufgebaut)
document.getElementById("sutrackpSVG").addEventListener("click", ev => {
	const target = ev.target.closest && ev.target.closest("[data-train]");
	if (!target) return;
	
	global.shiftDown = ev.shiftKey;     // showInfoWindow wertet global.shiftDown aus
	global.altDown   = ev.altKey;
	showTrainInfo(target.getAttribute("data-train"), ev.altKey, target.getAttribute("data-vehicle"));
	ev.stopPropagation();               // verhindert die Gleis-Auswertung in showElement()
});

// BroadcastChannel EEP_LIVE
let pendingData = null;   // Daten, die vor dem Laden der Anlage-Datei eintrafen
ch.onmessage = function(ev){
	const m = ev.data;
	
	if (m.type === "center") { // Ansicht auf eine bestimmte Position zentrieren
		if (window.global && global.SvgPanZoom) {
			global.SvgPanZoom.centerPosition([m.x, m.y, 0]);
		}
		
	} else if (m.type === "signalQuery") { // Klassifikation der Signalstellungen erfragen
		ch.postMessage({type: "signalInfo", signals: signalInfo(m.ids || [])});
		
	}	else if (m.type === "showTrack") {   // Gleis-Info ausrufen
		const GleissystemID =  String(m.GleissystemID);
		const GleisID =  String(m.GleisID);
		const Gleis = isLoaded() && getGleis(GleissystemID, GleisID);
		if (Gleis) {
			if (Gleis.mMid) { global.SvgPanZoom.centerPosition(Gleis.mMid); }
			if (window.showGleisInfo) { window.showGleisInfo(GleissystemID, GleisID); }
		}
		
	}	else if (m.type === "data") {
		pendingData = m.data;
		draw(m.data);
	}
};

// Erst 'ready' melden, wenn eine Anlage-Datei geladen wurde; dann auch zwischengespeicherte Daten zeichnen
function announceWhenLoaded(){
	if (isLoaded()) {
		ch.postMessage({type: "ready"});
		if (pendingData) { draw(pendingData); }
	} else {
		setTimeout(announceWhenLoaded, 500);
	}
}
announceWhenLoaded();
})();